/* PlayWithDoc service worker — OFFLINE-FIRST.
 * Generated by scripts/build-sw.mjs at build time (do not edit public/sw.js by hand; edit this template).
 *
 *  • On install it downloads the whole app shell: every page, script, style, font and the core engines.
 *  • Pages and static assets are served from cache first, so the site opens instantly and works with no connection.
 *  • Big optional engines (OCR, HEIC) are cached the first time they're used, or on demand from the "Offline" menu.
 *  • A new version installs quietly in the background and waits until the user chooses to reload.
 *  • Same-origin GET requests only — nothing here can send data anywhere.
 */
const VERSION = "__VERSION__";
const CORE = "af-core-" + VERSION;
const VENDOR = "af-vendor-__VENDOR__";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const core = await caches.open(CORE);
    const vendor = await caches.open(VENDOR);
    await Promise.allSettled(PRECACHE.map(async (url) => {
      const target = url.startsWith("/vendor/") ? vendor : core;
      if (await target.match(url)) return;
      const res = await fetch(url, { cache: "reload" });
      if (res.ok) await target.put(url, res);
    }));
  })());
});

self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key !== CORE && key !== VENDOR) await caches.delete(key);
    await self.clients.claim();
  })());
});

const isStatic = (p) => p.startsWith("/_next/static/") || p.startsWith("/icons/") || p === "/manifest.webmanifest" || /\.(woff2?|svg|png)$/.test(p);

async function cacheFirst(req, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) cache.put(req, res.clone());
  return res;
}

async function page(req, url) {
  const cache = await caches.open(CORE);
  const hit = await cache.match(url.pathname, { ignoreSearch: true });
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res.ok && !url.search) cache.put(url.pathname, res.clone());
    return res;
  } catch {
    return (await cache.match("/")) || Response.error();
  }
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || url.pathname === "/sw.js") return;

  if (req.mode === "navigate") { event.respondWith(page(req, url)); return; }
  if (url.pathname.startsWith("/vendor/")) { event.respondWith(cacheFirst(req, VENDOR)); return; }
  if (isStatic(url.pathname)) { event.respondWith(cacheFirst(req, CORE)); return; }

  // Everything else (e.g. RSC payloads for client-side navigation): try the network, fall back to cache.
  // If both fail, the framework falls back to a normal page load, which the cache above can serve.
  event.respondWith(fetch(req).catch(async () => (await caches.match(req)) || Response.error()));
});
